"use client"

import SneakerProductHero, { type SneakerVariant, type SneakerView } from "@/components/ui/sneaker-product-hero"

// One unbranded running shoe in three colourways, AI-generated for this demo
// (side and front three-quarter shots), cut out to transparency and inlined as
// WebP so nothing is fetched. Onyx's three-quarter shot is recoloured from Cobalt's.
const CLOUD = "data:image/webp;base64,"
const CLOUD_34 = "data:image/webp;base64,"
const COBALT = "data:image/webp;base64,"
const COBALT_34 = "data:image/webp;base64,"
const ONYX = "data:image/webp;base64,"
const ONYX_34 = "data:image/webp;base64,"

// Two real angles per colourway, then close-ups framed from the side shot.
const gallery = (side: string, front: string): SneakerView[] => [
  { src: side, label: "Side" },
  { src: front, label: "Front three-quarter" },
  { src: side, label: "Inside", mirror: true },
  { src: side, label: "Heel", focus: [0.86, 0.42], zoom: 1.7 },
  { src: side, label: "Laces", focus: [0.47, 0.34], zoom: 1.7 },
]

const variants: SneakerVariant[] = [
  { name: "Onyx", swatch: "#1d1d1f", tint: "#7fd8bd", src: ONYX, gallery: gallery(ONYX, ONYX_34), stock: { "39": 2 } },
  { name: "Cloud", swatch: "#e4e4e4", tint: "#ff9f6e", src: CLOUD, gallery: gallery(CLOUD, CLOUD_34) },
  { name: "Cobalt", swatch: "#2f4fd0", tint: "#5b7cff", src: COBALT, gallery: gallery(COBALT, COBALT_34), soldOut: ["36"] },
]

export default function Demo() {
  return <SneakerProductHero variants={variants} defaultVariant={1} />
}
